// Hand-written service of an existing NestJS application (never generated by gherkin-ai).
import { ConflictException, Injectable, NotFoundException, ServiceUnavailableException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { PrismaService } from '../prisma.service';
import { PlaceOrderDto } from './dto/place-order.dto';
import { OrderApprovedEvent } from './order-approved.event';
import { OrderStatus } from './order-status';

@Injectable()
export class OrdersService {
  constructor(private readonly prisma: PrismaService, private readonly eventEmitter: EventEmitter2) {}

  async place(dto: PlaceOrderDto) {
    const order = await this.prisma.order.create({ data: { customerEmail: dto.customerEmail, items: dto.items, status: OrderStatus.PENDING } });
    this.eventEmitter.emit('order.placed', { orderId: order.id });
    return order;
  }

  async approve(id: string) {
    const order = await this.prisma.order.findUnique({ where: { id } });
    if (!order) {
      throw new NotFoundException('Order not found');
    }
    if (order.status !== OrderStatus.PENDING) {
      throw new ConflictException('Only pending orders can be approved');
    }
    if (!this.prisma.isConnected) {
      throw new ServiceUnavailableException('Database unavailable');
    }
    order.status = OrderStatus.APPROVED;
    await this.prisma.order.update({ where: { id }, data: { status: order.status } });
    this.eventEmitter.emit('order.approved', new OrderApprovedEvent(id));
    return order;
  }

  async findOne(id: string) {
    const order = await this.prisma.order.findUnique({ where: { id } });
    if (!order) throw new NotFoundException('Order not found');
    return order;
  }

  async findAll() {
    return this.prisma.order.findMany();
  }
}
